// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint8 n, address[5] calldata addrs, uint96[5] calldata vals) public {
        uint256 calls = (uint256(n) % 5) + 1;
        for (uint256 i = 0; i < calls; i++) {
            address caller = addrs[i];
            uint256 amount = uint256(vals[i]);
            vm.assume(caller != address(0));
            vm.deal(caller, amount);
            vm.prank(caller);
            c.addToBalance{value: amount}();
        }
        for (uint256 i = 0; i < calls; i++) {
            address caller = addrs[i];
            uint256 amount = uint256(vals[i]);
            uint256 totalSent = 0;
            for (uint256 j = 0; j < calls; j++) {
                if (addrs[j] == caller) {
                    totalSent += uint256(vals[j]);
                }
            }
            uint256 balance = c.getBalance(caller);
            assertTrue(balance <= totalSent);
        }
    }
}
